
/**
 * lib/market.ts
 *
 * Black-market shop + robbery rules.
 *
 * Money remains in economy.ts; inventory remains in the market store.
 * Shop purchases and failed robbery bail payments contribute to the jackpot.
 *
 * Ammunition model:
 * - Each owned gun has its own magazine and reserve ammunition.
 * - One round is consumed per actual robbery attempt.
 * - Empty magazines reload automatically, using reserve ammunition only.
 * - No ammunition is generated by reloading.
 * - Ammo packs apply to one owned gun, defaulting to the equipped gun.
 * - Existing inventories are migrated lazily by normalize().
 *
 * Concurrency:
 * - Buying items/ammo and equipping guns lock the member.
 * - Robbery locks both members in sorted order.
 */

import { createStore } from './pluginStore.js';
import { getWallet, addCoins, deductCoins } from './economy.js';
import { contributeToJackpot } from './slotMachine.js';

const root = createStore('market');

if (typeof root.table !== 'function') {
  throw new Error('Market store does not support tables');
}

const inventoryTbl = root.table('inventory');

// ── Tunables ─────────────────────────────────────────────────────────────

export const MARKET_CONFIG = {
  BAIL: 20,
  BASE_SUCCESS: 0.70,
  MASK_SUCCESS: 0.90,
  STEAL_PERCENT: 0.70,

  NO_GUN_COOLDOWN_MS: 5 * 60_000,
  RELOAD_MS: 3 * 60_000, // fallback for guns without reloadMs

  NO_GUN_DAMAGE: 10,
  SHOP_REVENUE_TO_JACKPOT: true,
};

const DAY = 24 * 60 * 60_000;

export type ItemKind = 'protection' | 'mask' | 'gun';

export interface ShopItem {
  id: string;
  kind: ItemKind;
  name: string;
  emoji: string;
  price: number;
  durationMs?: number;
  life?: number;
  successRate?: number;

  /** Magazine capacity for guns. */
  rounds?: number;

  /** Damage dealt to protection per shot. */
  damage?: number;

  /** Initial reserve ammunition granted when the gun is purchased/migrated. */
  startingReserveAmmo?: number;

  /** Time required to reload an empty magazine. */
  reloadMs?: number;
}

