// ── Formatting helpers ───────────────────────────────────────────────────

export function fmtDuration(ms: number): string {
  const s = Math.max(0, Math.ceil(ms / 1000));
  const d = Math.floor(s / 86400);
  const h = Math.floor((s % 86400) / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;

  if (d > 0) return `${d}d ${h}h`;
  if (h > 0) return `${h}h ${m}m`;
  if (m > 0) return `${m}m ${sec}s`;
  return `${sec}s`;
}

export function lifeBar(
  life: number,
  max: number,
  size = 10,
): string {
  const filled = max > 0
    ? Math.max(0, Math.min(size, Math.ceil((life / max) * size)))
    : 0;

  return `${'█'.repeat(filled)}${'░'.repeat(size - filled)}`;
}

/**
 * 70% of the wallet, rounded down to an even number.
 * If the result would be zero, take the remaining wallet instead.
 */
export function evenSteal(coins: number): number {
  if (coins <= 0) return 0;

  const raw = Math.floor(coins * MARKET_CONFIG.STEAL_PERCENT);
  const even = raw - (raw % 2);

  return even > 0 ? even : coins;
}

// ── Per-user locks ───────────────────────────────────────────────────────

const lockTails = new Map<string, Promise<void>>();

async function withLock<T>(
  key: string,
  fn: () => Promise<T>,
): Promise<T> {
  const prev = lockTails.get(key) || Promise.resolve();

  let release!: () => void;
  const gate = new Promise<void>(resolve => {
    release = resolve;
  });

  const tail = prev.then(() => gate);
  lockTails.set(key, tail);

  await prev;

  try {
    return await fn();
  } finally {
    release();

    if (lockTails.get(key) === tail) {
      lockTails.delete(key);
    }
  }
}

async function withLocks<T>(
  keys: string[],
  fn: () => Promise<T>,
): Promise<T> {
  const sorted = [...new Set(keys)].sort();

  const run = (i: number): Promise<T> => {
    if (i >= sorted.length) return fn();

    return withLock(sorted[i], () => run(i + 1));
  };

  return run(0);
}

// ── Inventory ────────────────────────────────────────────────────────────

export interface ActiveProtection {
  itemId: string;
  expiresAt: number;
  life: number;
  maxLife: number;
}

export interface GunAmmoState {
  /** Rounds currently loaded. */
  magazineAmmo: number;

  /** Rounds available for future reloads. */
  reserveAmmo: number;

  /**
   * Epoch timestamp at which the current reload finishes.
   * Zero means no reload is pending.
   */
  reloadUntil: number;
}

export interface Inventory {
  protection: ActiveProtection | null;
  maskUntil: number;

  /** Owned weapon IDs; retained for compatibility with existing callers. */
  guns: string[];

  equippedGun: string | null;

  /** New per-weapon ammunition state, keyed by gun ID. */
  gunAmmo: Record<string, GunAmmoState>;

  /** Shared robbery cooldown; used for no-gun cooldowns and gun reloads. */
  cooldownUntil: number;
}

const emptyInventory = (): Inventory => ({
  protection: null,
  maskUntil: 0,
  guns: [],
  equippedGun: null,
  gunAmmo: {},
  cooldownUntil: 0,
});

function startingGunAmmo(gunId: string): GunAmmoState {
  const gun = ITEMS[gunId];

  return {
    magazineAmmo: gun?.rounds ?? 0,
    reserveAmmo: gun?.startingReserveAmmo ?? 0,
    reloadUntil: 0,
  };
}

function normalize(raw: any): Inventory {
  const inv: Inventory = {
    ...emptyInventory(),
    ...(raw || {}),
  };

  // Remove unknown/non-gun IDs and duplicate IDs.
  inv.guns = [...new Set(
    (Array.isArray(inv.guns) ? inv.guns : [])
      .filter((id: unknown): id is string =>
        typeof id === 'string' && ITEMS[id]?.kind === 'gun',
      ),
  )];

  if (
    inv.equippedGun &&
    !inv.guns.includes(inv.equippedGun)
  ) {
    inv.equippedGun = inv.guns[0] || null;
  }

  if (!inv.equippedGun && inv.guns.length > 0) {
    inv.equippedGun = inv.guns[0];
  }

  const rawAmmo =
    raw?.gunAmmo && typeof raw.gunAmmo === 'object'
      ? raw.gunAmmo
      : {};

  inv.gunAmmo = {};

  for (const gunId of inv.guns) {
    const saved = rawAmmo[gunId];

    if (!saved || typeof saved !== 'object') {
      // Legacy gun: the old system did not record reserve ammunition.
      // Grant the configured initial magazine and reserve exactly once
      // when this normalized inventory is persisted.
      inv.gunAmmo[gunId] = startingGunAmmo(gunId);
      continue;
    }

    const gun = ITEMS[gunId]!;

    inv.gunAmmo[gunId] = {
      magazineAmmo: Math.max(
        0,
        Math.min(
          gun.rounds ?? 0,
          Math.floor(Number(saved.magazineAmmo) || 0),
        ),
      ),
      reserveAmmo: Math.max(
        0,
        Math.floor(Number(saved.reserveAmmo) || 0),
      ),
      reloadUntil: Math.max(
        0,
        Math.floor(Number(saved.reloadUntil) || 0),
      ),
    };
  }

  inv.cooldownUntil = Math.max(
    0,
    Math.floor(Number(inv.cooldownUntil) || 0),
  );

  return inv;
}

/**
 * A normalized read does not itself persist migration changes.
 * The next successful mutation writes the normalized inventory.
 */
export async function getInventory(
  userId: string,
): Promise<Inventory> {
  return normalize(await inventoryTbl.get(userId));
}

async function mutateInventory(
  userId: string,
  mutator: (inv: Inventory) => void,
): Promise<Inventory> {
  return inventoryTbl.mutate(userId, (cur: any) => {
    const inv = normalize(cur);
    mutator(inv);
    return inv;
  });
}

export function activeProtection(
  inv: Inventory,
  now = Date.now(),
): ActiveProtection | null {
  const p = inv.protection;

  return p && p.expiresAt > now && p.life > 0
    ? p
    : null;
}

export function hasMask(
  inv: Inventory,
  now = Date.now(),
): boolean {
  return inv.maskUntil > now;
}

export function getGunAmmo(
  inv: Inventory,
  gunId: string,
): GunAmmoState | null {
  if (!inv.guns.includes(gunId)) return null;

  return inv.gunAmmo[gunId] ?? startingGunAmmo(gunId);
}

// ── Shop buying ──────────────────────────────────────────────────────────

export type BuyResult =
  | { ok: true; item: ShopItem; coinsLeft: number }
  | { ok: false; reason: 'unknown_item' }
  | {
      ok: false;
      reason: 'already_protected';
      current: ActiveProtection;
    }
  | { ok: false; reason: 'already_owned' }
  | { ok: false; reason: 'insufficient_funds'; coins: number }
  | { ok: false; reason: 'store_error' };

function grants(
  inv: Inventory,
  item: ShopItem,
  now: number,
): boolean {
  if (item.kind === 'protection') {
    return (
      inv.protection?.itemId === item.id &&
      inv.protection.expiresAt > now
    );
  }

  if (item.kind === 'mask') {
    return inv.maskUntil > now;
  }

  return (
    inv.guns.includes(item.id) &&
    !!inv.gunAmmo[item.id]
  );
}

export async function buyItem(
  userId: string,
  itemId: string,
): Promise<BuyResult> {
  const item = ITEMS[itemId];

  if (!item) {
    return { ok: false, reason: 'unknown_item' };
  }

  return withLock(userId, async () => {
    const now = Date.now();
    const before = await getInventory(userId);

    if (item.kind === 'protection') {
      const current = activeProtection(before, now);

      if (current) {
        return {
          ok: false,
          reason: 'already_protected',
          current,
        };
      }
    }

    if (
      item.kind === 'gun' &&
      before.guns.includes(item.id)
    ) {
      return { ok: false, reason: 'already_owned' };
    }

    const paid = await deductCoins(
      userId,
      item.price,
      {
        type: 'shop',
        note: `bought ${item.name}`,
      },
    );

    if (!paid.success) {
      return {
        ok: false,
        reason: 'insufficient_funds',
        coins: paid.wallet.coins,
      };
    }

    try {
      await mutateInventory(userId, inv => {
        if (item.kind === 'protection') {
          inv.protection = {
            itemId: item.id,
            expiresAt: now + item.durationMs!,
            life: item.life!,
            maxLife: item.life!,
          };
        } else if (item.kind === 'mask') {
          inv.maskUntil =
            Math.max(inv.maskUntil, now) + item.durationMs!;
        } else {
          inv.guns.push(item.id);
          inv.gunAmmo[item.id] = startingGunAmmo(item.id);

          const equipped = inv.equippedGun
            ? ITEMS[inv.equippedGun]
            : null;

          // Preserve the existing auto-equip upgrade behavior.
          if (
            !equipped ||
            item.damage! > (equipped.damage || 0)
          ) {
            inv.equippedGun = item.id;
          }
        }
      });

      const after = await getInventory(userId);

      if (!grants(after, item, now)) {
        throw new Error('inventory write did not persist');
      }
    } catch (err: any) {
      console.error(
        `[market] grant failed after payment (user=${userId} item=${item.id}):`,
        err?.message || err,
      );

      try {
        await addCoins(userId, item.price, {
          type: 'shop_refund',
          note: `refund: ${item.name} could not be delivered`,
        });
      } catch (refundErr: any) {
        console.error(
          `[market] CRITICAL: refund ALSO failed (user=${userId} amount=${item.price}):`,
          refundErr?.message || refundErr,
        );
      }

      return { ok: false, reason: 'store_error' };
    }

    if (MARKET_CONFIG.SHOP_REVENUE_TO_JACKPOT) {
      await contributeToJackpot(item.price).catch(
        (e: any) =>
          console.error(
            '[market] jackpot contribution failed:',
            e?.message || e,
          ),
      );
    }

    return {
      ok: true,
      item,
      coinsLeft: paid.wallet.coins,
    };
  });
}

// ── Ammunition purchases ─────────────────────────────────────────────────

export type BuyAmmoResult =
  | {
      ok: true;
      pack: AmmoPack;
      gun: ShopItem;
      roundsAdded: number;
      reserveAmmo: number;
      coinsLeft: number;
    }
  | { ok: false; reason: 'unknown_pack' }
  | { ok: false; reason: 'no_gun' }
  | { ok: false; reason: 'gun_not_owned' }
  | { ok: false; reason: 'insufficient_funds'; coins: number }
  | { ok: false; reason: 'store_error' };

/**
 * Buy ammunition for a particular owned gun.
 * If gunId is omitted, ammunition is assigned to the equipped gun.
 * Packs add to reserve ammunition; they never directly refill a magazine.
 */
export async function buyAmmoPack(
  userId: string,
  packId: string,
  gunId?: string,
): Promise<BuyAmmoResult> {
  const pack = AMMO_PACKS[packId];

  if (!pack) {
    return { ok: false, reason: 'unknown_pack' };
  }

  return withLock(userId, async () => {
    const before = await getInventory(userId);
    const targetGunId = gunId || before.equippedGun;

    if (!targetGunId) {
      return { ok: false, reason: 'no_gun' };
    }

    const gun = ITEMS[targetGunId];

    if (
      !gun ||
      gun.kind !== 'gun' ||
      !before.guns.includes(targetGunId)
    ) {
      return { ok: false, reason: 'gun_not_owned' };
    }

    const paid = await deductCoins(
      userId,
      pack.price,
      {
        type: 'shop',
        note: `bought ${pack.name} for ${gun.name}`,
      },
    );

    if (!paid.success) {
      return {
        ok: false,
        reason: 'insufficient_funds',
        coins: paid.wallet.coins,
      };
    }

    try {
      await mutateInventory(userId, inv => {
        // Recheck ownership inside the mutation.
        if (!inv.guns.includes(targetGunId)) {
          throw new Error('gun ownership changed during ammo purchase');
        }

        const state =
          inv.gunAmmo[targetGunId] ??
          startingGunAmmo(targetGunId);

        state.reserveAmmo += pack.rounds;
        inv.gunAmmo[targetGunId] = state;
      });

      const after = await getInventory(userId);
      const state = after.gunAmmo[targetGunId];

      if (
        !after.guns.includes(targetGunId) ||
        !state ||
        state.reserveAmmo < pack.rounds
      ) {
        throw new Error('ammunition write did not persist');
      }

      if (MARKET_CONFIG.SHOP_REVENUE_TO_JACKPOT) {
        await contributeToJackpot(pack.price).catch(
          (e: any) =>
            console.error(
              '[market] ammo jackpot contribution failed:',
              e?.message || e,
            ),
        );
      }

      return {
        ok: true,
        pack,
        gun,
        roundsAdded: pack.rounds,
        reserveAmmo: state.reserveAmmo,
        coinsLeft: paid.wallet.coins,
      };
    } catch (err: any) {
      console.error(
        `[market] ammo grant failed after payment (user=${userId} pack=${pack.id} gun=${targetGunId}):`,
        err?.message || err,
      );

      try {
        await addCoins(userId, pack.price, {
          type: 'shop_refund',
          note: `refund: ${pack.name} could not be delivered`,
        });
      } catch (refundErr: any) {
        console.error(
          `[market] CRITICAL: ammo refund ALSO failed (user=${userId} amount=${pack.price}):`,
          refundErr?.message || refundErr,
        );
      }

      return { ok: false, reason: 'store_error' };
    }
  });
}

// ── Equipping guns ───────────────────────────────────────────────────────

export async function equipGun(
  userId: string,
  gunId: string,
): Promise<{ ok: boolean; gun?: ShopItem }> {
  const gun = ITEMS[gunId];

  if (!gun || gun.kind !== 'gun') {
    return { ok: false };
  }

  return withLock(userId, async () => {
    const inv = await getInventory(userId);

    if (!inv.guns.includes(gunId)) {
      return { ok: false };
    }

    await mutateInventory(userId, i => {
      i.equippedGun = gunId;
    });

    return { ok: true, gun };
  });
}

// ── Robbery ──────────────────────────────────────────────────────────────

export interface RobContext {
  gun: ShopItem | null;
  masked: boolean;
  successRate: number;

  /** Magazine ammunition remaining after the attempt; null when reloading. */
  roundsLeft: number | null;

  /** Cooldown applied by this attempt, if any. */
  cooldownMs: number;
}

export type RobResult =
  | { ok: false; reason: 'self' }
  | { ok: false; reason: 'error' }
  | { ok: false; reason: 'poor'; coins: number }
  | {
      ok: false;
      reason: 'cooldown';
      remainingMs: number;
      gun: ShopItem | null;
      reloading: boolean;
    }
  | {
      ok: false;
      reason: 'no_ammo';
      gun: ShopItem;
      magazineAmmo: number;
      reserveAmmo: number;
    }
  | { ok: true; outcome: 'victim_broke' }
  | ({
      ok: true;
      outcome: 'caught';
      bail: number;
      coinsAfter: number;
    } & RobContext)
  | ({
      ok: true;
      outcome: 'blocked';
      protectionName: string;
      damage: number;
      lifeLeft: number;
      lifeMax: number;
      broken: boolean;
    } & RobContext)
  | ({
      ok: true;
      outcome: 'success';
      stolen: number;
      coinsAfter: number;
    } & RobContext);

export async function attemptRob(
  robberId: string,
  victimId: string,
  rng: () => number = Math.random,
): Promise<RobResult> {
  if (robberId === victimId) {
    return { ok: false, reason: 'self' };
  }

  const {
    BAIL,
    BASE_SUCCESS,
    MASK_SUCCESS,
    NO_GUN_COOLDOWN_MS,
    RELOAD_MS,
    NO_GUN_DAMAGE,
  } = MARKET_CONFIG;

  return withLocks([robberId, victimId], async (): Promise<RobResult> => {
    const now = Date.now();

    // 1. Bail is always required.
    const robberWallet = await getWallet(robberId);

    if (robberWallet.coins < BAIL) {
      return {
        ok: false,
        reason: 'poor',
        coins: robberWallet.coins,
      };
    }

    // 2. Read weapon and cooldown state.
    let robberInv = await getInventory(robberId);

    const gun = robberInv.equippedGun
      ? ITEMS[robberInv.equippedGun] ?? null
      : null;

    if (robberInv.cooldownUntil > now) {
      return {
        ok: false,
        reason: 'cooldown',
        remainingMs: robberInv.cooldownUntil - now,
        gun,
        reloading: !!gun &&
          (robberInv.gunAmmo[gun.id]?.reloadUntil ?? 0) > now,
      };
    }

    // 3. An empty victim wallet consumes no round and does not start a reload.
    if ((await getWallet(victimId)).coins <= 0) {
      return { ok: true, outcome: 'victim_broke' };
    }

    // 4. Ensure the equipped gun is loaded before an attempt can be made.
    let gunState: GunAmmoState | null = null;

    if (gun) {
      gunState = robberInv.gunAmmo[gun.id] ?? startingGunAmmo(gun.id);

      if (gunState.magazineAmmo <= 0) {
        if (gunState.reserveAmmo <= 0) {
          return {
            ok: false,
            reason: 'no_ammo',
            gun,
            magazineAmmo: 0,
            reserveAmmo: 0,
          };
        }

        const reloadUntil = gunState.reloadUntil;

        // A previous reload is still running.
        if (reloadUntil > now) {
          await mutateInventory(robberId, inv => {
            inv.cooldownUntil = reloadUntil;
          });

          return {
            ok: false,
            reason: 'cooldown',
            remainingMs: reloadUntil - now,
            gun,
            reloading: true,
          };
        }

        // If the previous reload has completed, transfer real reserve rounds.
        // If no reload was pending, start one now rather than granting rounds.
        if (reloadUntil === 0) {
          const duration = gun.reloadMs ?? RELOAD_MS;
          const until = now + duration;

          await mutateInventory(robberId, inv => {
            const state = inv.gunAmmo[gun.id];

            if (state) {
              state.reloadUntil = until;
            }

            inv.cooldownUntil = until;
          });

          return {
            ok: false,
            reason: 'cooldown',
            remainingMs: duration,
            gun,
            reloading: true,
          };
        }

        // A completed reload consumes reserve ammunition to refill the magazine.
        await mutateInventory(robberId, inv => {
          const state = inv.gunAmmo[gun.id];

          if (!state || state.magazineAmmo > 0) return;

          const capacity = gun.rounds ?? 0;
          const loaded = Math.min(capacity, state.reserveAmmo);

          state.magazineAmmo = loaded;
          state.reserveAmmo -= loaded;
          state.reloadUntil = 0;
          inv.cooldownUntil = 0;
        });

        robberInv = await getInventory(robberId);
        gunState = robberInv.gunAmmo[gun.id];

        if (!gunState || gunState.magazineAmmo <= 0) {
          return {
            ok: false,
            reason: 'no_ammo',
            gun,
            magazineAmmo: gunState?.magazineAmmo ?? 0,
            reserveAmmo: gunState?.reserveAmmo ?? 0,
          };
        }
      }
    }

    // 5. Consume one round for the actual attempt.
    // No-gun attempts retain their original five-minute cooldown.
    let roundsLeft: number | null = null;
    let cooldownMs = 0;

    if (!gun) {
      cooldownMs = NO_GUN_COOLDOWN_MS;

      await mutateInventory(robberId, inv => {
        inv.cooldownUntil = now + cooldownMs;
      });
    } else {
      const state = gunState!;

      // The current magazine must contain a round.
      if (state.magazineAmmo <= 0) {
        return {
          ok: false,
          reason: 'no_ammo',
          gun,
          magazineAmmo: state.magazineAmmo,
          reserveAmmo: state.reserveAmmo,
        };
      }

      const remainingMagazine = state.magazineAmmo - 1;

      if (remainingMagazine === 0 && state.reserveAmmo > 0) {
        // The last shot starts automatic reloading.
        cooldownMs = gun.reloadMs ?? RELOAD_MS;
      }

      await mutateInventory(robberId, inv => {
        const current = inv.gunAmmo[gun.id];

        if (!current || current.magazineAmmo <= 0) {
          throw new Error('magazine changed before round consumption');
        }

        current.magazineAmmo -= 1;

        if (
          current.magazineAmmo === 0 &&
          current.reserveAmmo > 0
        ) {
          current.reloadUntil = now + cooldownMs;
          inv.cooldownUntil = current.reloadUntil;
        } else {
          current.reloadUntil = 0;
          inv.cooldownUntil = 0;
        }
      });

      const afterShot = await getInventory(robberId);
      const afterAmmo = afterShot.gunAmmo[gun.id];

      roundsLeft =
        cooldownMs > 0
          ? null
          : (afterAmmo?.magazineAmmo ?? 0);
    }

    const masked = hasMask(robberInv, now);
    const successRate = masked ? MASK_SUCCESS : BASE_SUCCESS;

    const ctx: RobContext = {
      gun,
      masked,
      successRate,
      roundsLeft,
      cooldownMs,
    };

    // 6. Caught: pay bail into the jackpot.
    if (!(rng() < successRate)) {
      const paid = await deductCoins(
        robberId,
        BAIL,
        {
          type: 'rob_bail',
          counterpartyId: victimId,
          note: 'caught robbing — bail paid to the reserve',
        },
      );

      if (paid.success) {
        await contributeToJackpot(BAIL).catch(
          (e: any) =>
            console.error(
              '[market] bail -> jackpot failed:',
              e?.message || e,
            ),
        );
      }

      return {
        ok: true,
        outcome: 'caught',
        bail: paid.success ? BAIL : 0,
        coinsAfter: paid.wallet.coins,
        ...ctx,
      };
    }

    // 7. Successful attack against active protection damages its life bar.
    const victimInv = await getInventory(victimId);

    if (activeProtection(victimInv, now)) {
      const damage = gun
        ? gun.damage!
        : NO_GUN_DAMAGE;

      let absorbed = false;
      let before = 0;
      let after = 0;
      let broken = false;
      let protectionId = '';
      let lifeMax = 0;

      await mutateInventory(victimId, inv => {
        const p = inv.protection;

        if (!p || p.expiresAt <= now || p.life <= 0) {
          return;
        }

        absorbed = true;
        protectionId = p.itemId;
        before = p.life;
        lifeMax = p.maxLife;
        p.life = Math.max(0, p.life - damage);
        after = p.life;

        if (p.life <= 0) {
          inv.protection = null;
          broken = true;
        }
      });

      if (absorbed) {
        return {
          ok: true,
          outcome: 'blocked',
          protectionName:
            ITEMS[protectionId]?.name || 'Protection',
          damage: before - after,
          lifeLeft: after,
          lifeMax,
          broken,
          ...ctx,
        };
      }
    }

    // 8. Successful robbery against an unprotected victim.
    for (let tries = 0; tries < 2; tries++) {
      const fresh = (await getWallet(victimId)).coins;
      const amount = evenSteal(fresh);

      if (amount <= 0) {
        return { ok: true, outcome: 'victim_broke' };
      }

      const taken = await deductCoins(
        victimId,
        amount,
        {
          type: 'rob_loss',
          counterpartyId: robberId,
          note: 'robbed',
        },
      );

      if (!taken.success) {
        continue;
      }

      try {
        const saved = await addCoins(
          robberId,
          amount,
          {
            type: 'rob_win',
            counterpartyId: victimId,
            note: 'robbery',
          },
        );

        return {
          ok: true,
          outcome: 'success',
          stolen: amount,
          coinsAfter: saved.coins,
          ...ctx,
        };
      } catch (err: any) {
        console.error(
          `[market] rob credit failed after debit (robber=${robberId} victim=${victimId} amount=${amount}):`,
          err?.message || err,
        );

        try {
          await addCoins(victimId, amount, {
            type: 'rob_refund',
            counterpartyId: robberId,
            note: 'auto-refund: robbery credit failed',
          });
        } catch (refundErr: any) {
          console.error(
            `[market] CRITICAL: rob refund ALSO failed (victim=${victimId} amount=${amount}):`,
            refundErr?.message || refundErr,
          );
        }

        return { ok: false, reason: 'error' };
      }
    }

    return { ok: true, outcome: 'victim_broke' };
  });
}
